      <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="name-basil">Mark as planted</button>
    </li>
    <li class="card" data-light="sun">
      <h2 id="name-sunflower">Sunflower</h2>
      <span class="tag">Loves sun</span>
      <p>A tall, cheerful flower that wants full sun and plenty of space.</p>
      <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="name-sunflower">Mark as planted</button>
    </li>
    <li class="card" data-light="shade">
      <h2 id="name-mint">Mint</h2>
      <span class="tag">Likes shade</span>
      <p>A hardy herb that is happy in cooler, shadier spots.</p>
      <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="name-mint">Mark as planted</button>
    </li>
  </ul>
</main>

<script>
(function () {
  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));
  var status = document.getElementById('status');
  var labels = { all: 'all plants', sun: 'plants that love sun', shade: 'plants that like shade' };

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === 'all' || card.dataset.light === filter;
      card.hidden = !match;
      if (match) shown++;
    });
    filterBtns.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.dataset.filter === filter));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' — ' + labels[filter] + '.';
  }

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    btn.addEventListener('click', function () {
      var planted = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(planted));
      btn.textContent = planted ? 'Planted' : 'Mark as planted';
      card.classList.toggle('is-planted', planted);
    });
  });

  applyFilter('all');
})();
</script>
